from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print(fib(80))
print(fib.cache_info())

from functools import total_ordering, cached_property

@total_ordering
class Version:
    def __init__(self, n):
        self.n = n
    def __eq__(self, other):
        return self.n == other.n
    def __lt__(self, other):
        return self.n < other.n

print(Version(1) < Version(2), Version(3) >= Version(2), Version(2) > Version(5))

class Data:
    @cached_property
    def heavy(self):
        print("computing")
        return 42

d = Data()
print(d.heavy, d.heavy)

from functools import singledispatch

@singledispatch
def show(x):
    return f"something: {x}"

@show.register(int)
def _(x):
    return f"number {x}"

@show.register(list)
def _(x):
    return f"list of {len(x)}"

print(show(5), show([1, 2]), show("a"))

from functools import cmp_to_key

def compare(a, b):
    return len(a) - len(b) or (a > b) - (a < b)

print(sorted(["bb", "a", "cc", "b"], key=cmp_to_key(compare)))

from functools import lru_cache, reduce

try:
    reduce(lambda a, b: a + b, [])
except TypeError:
    print("reduce without an initial value")

@lru_cache
def total(xs):
    return sum(xs)

try:
    total([1, 2])
except TypeError as e:
    print(e)
